import '../core/protocol.dart'; import '../models/contact.dart';
class ContactBook { ContactBook(List<EmergencyContact> contacts):_contacts=List.of(contacts)..sort((a,b)=>a.priority.compareTo(b.priority)); final List<EmergencyContact> _contacts; List<EmergencyContact> get contacts=>List.unmodifiable(_contacts);
 String? validate(EmergencyContact contact,{int? replacing}) { if(!contact.isValid)return 'Enter a name and valid phone number.'; if(replacing==null&&_contacts.length>=maxContacts)return 'Only $maxContacts emergency contacts are allowed.'; for(var i=0;i<_contacts.length;i++){if(i!=replacing&&_contacts[i].normalizedPhone==contact.normalizedPhone)return 'That phone number is already configured.';} return null; }
 void add(EmergencyContact contact){final error=validate(contact);if(error!=null)throw ArgumentError(error);_contacts.add(EmergencyContact(name:contact.name.trim(),phone:contact.normalizedPhone,enabled:contact.enabled,priority:_contacts.length+1));}
 void replace(int index,EmergencyContact contact){final error=validate(contact,replacing:index);if(error!=null)throw ArgumentError(error);_contacts[index]=EmergencyContact(name:contact.name.trim(),phone:contact.normalizedPhone,enabled:contact.enabled,priority:index+1);}
 void remove(int index){_contacts.removeAt(index);_reorder();} void setEnabled(int index,bool enabled){final c=_contacts[index];_contacts[index]=EmergencyContact(name:c.name,phone:c.phone,enabled:enabled,priority:c.priority);} void move(int oldIndex,int newIndex){final c=_contacts.removeAt(oldIndex);_contacts.insert(newIndex,c);_reorder();} void _reorder(){for(var i=0;i<_contacts.length;i++){final c=_contacts[i];_contacts[i]=EmergencyContact(name:c.name,phone:c.phone,enabled:c.enabled,priority:i+1);}}
}
